#include <stdio.h>
#include <string.h>
#include <stdbool.h>

static bool is_digit(char c) {
    return c >= '0' && c <= '9';
}

static bool is_leap_year(int year) {
    if (year % 4 != 0) return false;
    if (year % 100 != 0) return true;
    return (year % 400 == 0);
}

static const int days_in_month[12] = {
    31, 28, 31, 30, 31, 30,
    31, 31, 30, 31, 30, 31
};

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }

    const char *s = argv[1];
    if (strlen(s) != 10) {
        puts("INVALID");
        return 0;
    }

    if (s[4] != '-' || s[7] != '-') {
        puts("INVALID");
        return 0;
    }

    for (int i = 0; i < 10; ++i) {
        if (i == 4 || i == 7) continue;
        if (!is_digit(s[i])) {
            puts("INVALID");
            return 0;
        }
    }

    int year = (s[0] - '0') * 1000 + (s[1] - '0') * 100 + (s[2] - '0') * 10 + (s[3] - '0');
    int month = (s[5] - '0') * 10 + (s[6] - '0');
    int day = (s[8] - '0') * 10 + (s[9] - '0');

    if (month < 1 || month > 12) {
        puts("INVALID");
        return 0;
    }
    if (day < 1) {
        puts("INVALID");
        return 0;
    }

    int max_day = days_in_month[month - 1];
    if (month == 2 && is_leap_year(year)) {
        max_day = 29;
    }

    if (day > max_day) {
        puts("INVALID");
        return 0;
    }

    puts("VALID");
    return 0;
}
